import {
  Slider as SliderPrimitive,
  useSlider,
  useSliderContext,
} from '@ark-ui/solid/slider';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { For, onCleanup, onMount, splitProps } from 'solid-js';
import styles from './Slider.module.css';

function SliderRoot(props: ComponentProps<typeof SliderPrimitive.Root>) {
  const [local, others] = splitProps(props, [
    'asChild',
    'children',
    'class',
    'defaultValue',
    'readOnly',
    'value',
  ]);

  return (
    <SliderPrimitive.Root
      asChild={local.asChild}
      defaultValue={local.defaultValue}
      value={local.value}
      data-slot="slider-root"
      data-readonly={local.readOnly ? '' : undefined}
      class={clsx(styles.root, local.class)}
      readOnly={local.readOnly}
      {...others}
    >
      {local.children}
    </SliderPrimitive.Root>
  );
}

function SliderRootProvider(props: ComponentProps<typeof SliderPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['asChild', 'class', 'value']);

  return (
    <SliderPrimitive.RootProvider
      asChild={local.asChild}
      value={local.value}
      data-slot="slider-root-provider"
      class={clsx(styles.root, local.class)}
      {...others}
    />
  );
}

function SliderLabel(props: ComponentProps<typeof SliderPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SliderPrimitive.Label
      data-slot="slider-label"
      class={clsx(styles.label, local.class)}
      {...others}
    />
  );
}

function SliderValueText(props: ComponentProps<typeof SliderPrimitive.ValueText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SliderPrimitive.ValueText
      data-slot="slider-value-text"
      class={clsx(styles.valueText, local.class)}
      {...others}
    />
  );
}

function SliderControl(props: ComponentProps<typeof SliderPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SliderPrimitive.Control
      data-slot="slider-control"
      class={clsx(styles.control, local.class)}
      {...others}
    />
  );
}

function SliderTrack(props: ComponentProps<typeof SliderPrimitive.Track>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SliderPrimitive.Track
      data-slot="slider-track"
      class={clsx(styles.track, local.class)}
      {...others}
    />
  );
}

function SliderRange(props: ComponentProps<typeof SliderPrimitive.Range>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SliderPrimitive.Range
      data-slot="slider-range"
      class={clsx(styles.range, local.class)}
      {...others}
    />
  );
}

function SliderThumb(props: ComponentProps<typeof SliderPrimitive.Thumb>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <SliderPrimitive.Thumb
      asChild={local.asChild}
      data-slot="slider-thumb"
      class={clsx(styles.thumb, local.class)}
      {...others}
    >
      {local.children}
      <SliderHiddenInput />
    </SliderPrimitive.Thumb>
  );
}

function SliderHiddenInput() {
  const slider = useSliderContext();
  const initialValue = [...slider().value];
  let inputRef: HTMLInputElement | undefined;

  onMount(() => {
    const formElement = inputRef?.form;

    if (!formElement) return;

    const handleReset = () => {
      queueMicrotask(() => slider().setValue(initialValue));
    };

    formElement.addEventListener('reset', handleReset);
    onCleanup(() => formElement.removeEventListener('reset', handleReset));
  });

  return (
    <SliderPrimitive.HiddenInput
      ref={(element) => (inputRef = element)}
      data-slot="slider-hidden-input"
    />
  );
}

function SliderThumbs(props: { class?: string }) {
  const slider = useSliderContext();

  return (
    <For each={slider().value}>
      {(_, index) => <SliderThumb index={index()} class={props.class} />}
    </For>
  );
}

function SliderMarkerGroup(props: ComponentProps<typeof SliderPrimitive.MarkerGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SliderPrimitive.MarkerGroup
      data-slot="slider-marker-group"
      class={clsx(styles.markerGroup, local.class)}
      {...others}
    />
  );
}

function SliderMarker(props: ComponentProps<typeof SliderPrimitive.Marker>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SliderPrimitive.Marker
      data-slot="slider-marker"
      class={clsx(styles.marker, local.class)}
      {...others}
    />
  );
}

function SliderDraggingIndicator(props: ComponentProps<typeof SliderPrimitive.DraggingIndicator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SliderPrimitive.DraggingIndicator
      data-slot="slider-dragging-indicator"
      class={clsx(styles.draggingIndicator, local.class)}
      {...others}
    />
  );
}

type SliderComponent = typeof SliderRoot & {
  Root: typeof SliderRoot;
  RootProvider: typeof SliderRootProvider;
  Context: typeof SliderPrimitive.Context;
  useSlider: typeof useSlider;
  useSliderContext: typeof useSliderContext;
  Label: typeof SliderLabel;
  ValueText: typeof SliderValueText;
  Control: typeof SliderControl;
  Track: typeof SliderTrack;
  Range: typeof SliderRange;
  Thumb: typeof SliderThumb;
  Thumbs: typeof SliderThumbs;
  MarkerGroup: typeof SliderMarkerGroup;
  Marker: typeof SliderMarker;
  DraggingIndicator: typeof SliderDraggingIndicator;
};

const Slider: SliderComponent = Object.assign(SliderRoot, {
  Root: SliderRoot,
  RootProvider: SliderRootProvider,
  Context: SliderPrimitive.Context,
  useSlider,
  useSliderContext,
  Label: SliderLabel,
  ValueText: SliderValueText,
  Control: SliderControl,
  Track: SliderTrack,
  Range: SliderRange,
  Thumb: SliderThumb,
  Thumbs: SliderThumbs,
  MarkerGroup: SliderMarkerGroup,
  Marker: SliderMarker,
  DraggingIndicator: SliderDraggingIndicator,
});

export { Slider, useSlider, useSliderContext };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: var(--moduix-slider-gap, var(--moduix-spacing-2));
    width: var(--moduix-slider-width, 12rem);
    max-inline-size: 100%;
    color: var(--moduix-slider-color, var(--moduix-color-foreground));

    &[data-orientation='vertical'] {
      display: grid;
      grid-template-areas:
        'label value'
        'control markers';
      grid-template-columns: auto max-content;
      grid-template-rows: auto minmax(0, 1fr);
      column-gap: var(--moduix-slider-marker-group-margin-inline-start, var(--moduix-spacing-2));
      width: var(--moduix-slider-width-vertical, max-content);
      height: var(--moduix-slider-height, 12rem);
      align-items: center;

      & .label {
        grid-area: label;
      }

      & .valueText {
        grid-area: value;
        justify-self: end;
      }

      & .control {
        grid-area: control;
      }

      & .markerGroup {
        grid-area: markers;
      }
    }

    &[data-disabled] {
      opacity: var(--moduix-slider-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .label {
    color: var(
      --moduix-slider-label-color,
      var(--moduix-slider-color, var(--moduix-color-foreground))
    );
    font-size: var(--moduix-slider-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-slider-label-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-slider-label-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
  }

  .valueText {
    color: var(
      --moduix-slider-value-text-color,
      var(--moduix-slider-color, var(--moduix-color-foreground))
    );
    font-size: var(--moduix-slider-value-text-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-slider-value-text-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-slider-value-text-line-height, var(--moduix-line-height-text-sm));
    text-align: right;
  }

  .control {
    position: relative;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    width: 100%;
    min-height: var(--moduix-slider-control-size, var(--moduix-spacing-5));
    touch-action: none;
    user-select: none;
    cursor: pointer;

    &[data-orientation='vertical'] {
      flex-direction: column;
      width: var(--moduix-slider-control-size, var(--moduix-spacing-5));
      height: 100%;
      min-height: 0;
    }

    &[data-disabled] {
      cursor: default;
    }

    .root[data-readonly] & {
      cursor: default;
    }
  }

  .track {
    flex: 1;
    width: 100%;
    height: var(--moduix-slider-track-size, var(--moduix-spacing-1-5));
    overflow: hidden;
    border-radius: var(--moduix-slider-track-radius, var(--moduix-radius-full));
    background-color: var(--moduix-slider-track-bg, var(--moduix-color-muted));
    box-shadow: inset 0 0 0 var(--moduix-slider-track-border-width, var(--moduix-border-width-sm))
      var(--moduix-slider-track-border-color, var(--moduix-color-border));
    user-select: none;

    &[data-orientation='vertical'] {
      width: var(--moduix-slider-track-size, var(--moduix-spacing-1-5));
      height: 100%;
    }

    &[data-invalid] {
      box-shadow: inset 0 0 0 var(--moduix-slider-track-border-width, var(--moduix-border-width-sm))
        var(--moduix-slider-track-border-color-invalid, var(--moduix-color-destructive));
    }
  }

  .range {
    height: 100%;
    border-radius: var(--moduix-slider-range-radius, inherit);
    background-color: var(--moduix-slider-range-bg, var(--moduix-color-primary));

    &[data-orientation='vertical'] {
      width: 100%;
    }

    &[data-invalid] {
      background-color: var(--moduix-slider-range-bg-invalid, var(--moduix-color-destructive));
    }
  }

  .thumb {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-slider-thumb-size, var(--moduix-spacing-4));
    height: var(--moduix-slider-thumb-size, var(--moduix-spacing-4));
    border: var(--moduix-slider-thumb-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-slider-thumb-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-slider-thumb-radius, var(--moduix-radius-full));
    background-color: var(--moduix-slider-thumb-bg, var(--moduix-color-background));
    box-shadow: var(--moduix-slider-thumb-shadow, var(--moduix-shadow-sm));
    outline: 0;
    user-select: none;
    transition:
      border-color var(--moduix-slider-transition, var(--moduix-transition-default)),
      background-color var(--moduix-slider-transition, var(--moduix-transition-default)),
      box-shadow var(--moduix-slider-transition, var(--moduix-transition-default));

    &[data-dragging] {
      border-color: var(--moduix-slider-focus-ring-color, var(--moduix-color-ring));
      box-shadow:
        0 0 0 var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
          var(--moduix-slider-focus-ring-color, var(--moduix-color-ring)),
        var(--moduix-slider-thumb-shadow-dragging, var(--moduix-shadow-md));
    }

    &:focus-visible {
      border-color: var(--moduix-slider-focus-ring-color, var(--moduix-color-ring));
      box-shadow: 0 0 0 var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        var(--moduix-slider-focus-ring-color, var(--moduix-color-ring));
    }

    &[data-disabled] {
      pointer-events: none;
    }

    &[data-invalid] {
      border-color: var(
        --moduix-slider-thumb-border-color-invalid,
        var(--moduix-color-destructive)
      );

      &:focus-visible {
        box-shadow: 0 0 0 var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
          var(
            --moduix-slider-thumb-focus-ring-color-invalid,
            var(--moduix-slider-thumb-border-color-invalid, var(--moduix-color-destructive))
          );
      }
    }
  }

  .draggingIndicator {
    top: calc(-1 * var(--moduix-spacing-8));
    padding: var(--moduix-spacing-1) var(--moduix-spacing-2);
    border-radius: var(--moduix-slider-dragging-indicator-radius, var(--moduix-radius-sm));
    background-color: var(--moduix-slider-dragging-indicator-bg, var(--moduix-color-foreground));
    color: var(--moduix-slider-dragging-indicator-color, var(--moduix-color-background));
    font-size: var(--moduix-slider-dragging-indicator-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-slider-dragging-indicator-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-slider-dragging-indicator-line-height, 1);
    white-space: nowrap;
    pointer-events: none;
  }

  .markerGroup {
    display: flex;
    justify-content: space-between;
    margin-block-start: var(--moduix-slider-marker-group-margin-top, var(--moduix-spacing-2));

    &[data-orientation='vertical'] {
      flex-direction: column;
      height: 100%;
      margin: 0;
    }
  }

  .marker {
    position: relative;
    color: var(--moduix-slider-marker-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-slider-marker-font-size, var(--moduix-text-xs));
    line-height: var(--moduix-slider-marker-line-height, var(--moduix-line-height-text-xs));

    &::before {
      position: absolute;
      inset-block-start: calc(-1 * var(--moduix-spacing-2));
      inset-inline-start: 50%;
      width: var(--moduix-slider-marker-dot-size, var(--moduix-spacing-1));
      height: var(--moduix-slider-marker-dot-size, var(--moduix-spacing-1));
      border-radius: var(--moduix-radius-full);
      background-color: var(--moduix-slider-marker-dot-bg, var(--moduix-color-border));
      content: '';
      transform: translateX(-50%);
    }

    &:is([data-state='under-value'], [data-state='at-value'])::before {
      background-color: var(
        --moduix-slider-marker-dot-bg-active,
        var(--moduix-slider-range-bg, var(--moduix-color-primary))
      );
    }

    .root[data-invalid] &:is([data-state='under-value'], [data-state='at-value'])::before {
      background-color: var(
        --moduix-slider-marker-dot-bg-active-invalid,
        var(--moduix-slider-range-bg-invalid, var(--moduix-color-destructive))
      );
    }

    &[data-orientation='vertical']::before {
      inset-block-start: 50%;
      inset-inline-start: calc(-1 * var(--moduix-spacing-2));
      transform: translate(-50%, -50%);
    }
  }
}
